/**
 * 登录 Controller
 * @author ThinkGem
 * @version 2020-9-19
 */
@Controller
@Tag(name = "Login - 登录公共")
@RequestMapping(value = "${adminPath}")
@ConditionalOnProperty(name="user.enabled", havingValue="true", matchIfMissing=true)
public class LoginController extends BaseController

/**
	 * 登录成功，进入管理首页
	 */
	@RequestMapping(value = "index")
	public String index(HttpServletRequest request, HttpServletResponse response, Model model) {
		// 地址中如果包含JSESSIONID，则跳转一次，去掉JSESSIONID信息。
		if (StringUtils.containsIgnoreCase(request.getRequestURI(), ";JSESSIONID=")){
			redirectUrl(request, response, "/index");
			return null;
		}

		// 获取登录用户信息，未加载shiro模块时会为空，直接访问则提示操作权限不足。
		Subject subject = UserUtils.getSubject();
		LoginInfo loginInfo = UserUtils.getLoginInfo(subject);
		if(loginInfo == null){
			subject.logout();
			redirectUrl(request, response, "/login");
			return null;
		}

		// 当前用户对象信息
		User user = UserUtils.get(loginInfo.getId());
		if (user == null){
			subject.logout();
			redirectUrl(request, response, "/login");
			return null;
		}

		// 如果是登录操作，则初始化一些登录参数
		Session session = UserUtils.getSession(subject);
		boolean isLogin = Global.TRUE.equals(session.getAttribute(BaseAuthorizingRealm.IS_LOGIN_OPER));
		if (isLogin){
			// 清除登录状态，防止下次调用误认为是登录
			session.removeAttribute(BaseAuthorizingRealm.IS_LOGIN_OPER);

			// 设置共享SessionId的Cookie值（第三方系统使用）
			String cookieName = Global.getProperty("session.shareSessionIdCookieName");
			if (StringUtils.isNotBlank(cookieName)){
				CookieUtils.setCookie(response, cookieName, (String)session.getId(), "/");
			}

			// 如果登录设置了语言，则切换语言
			if (loginInfo.getParam("lang") != null){
				Global.setLang(loginInfo.getParam("lang"), request, response);
			}

			// 根据当前用户子系统，切换到默认系统下
			for(Role role : user.getRoleList()) {
				if (role.getSysCodes() != null) {
					String sysCode = null;
					for (String code : StringUtils.splitComma(role.getSysCodes())) {
						if (StringUtils.isNotBlank(code)) {
							sysCode = code;
							break;
						}
					}
					if (sysCode != null) {
						session.setAttribute("sysCode", sysCode);
						MenuUtils.clearAuthInfo(session);
						break;
					}
				}
			}
		}

		// 验证下用户权限，以便调用doGetAuthorizationInfo方法
		else if (!subject.isPermitted("user")){
			subject.logout();
			redirectUrl(request, response, "/login");
			return null;
		}

		// 获取当前会话对象，并返回一些数据
		if (!StringUtils.equals(request.getParameter("__be"), Global.YES)) {
			model.addAllAttributes(FormFilter.getLoginSuccessData(request, response, user, session));
		}

		// 获取登录成功后跳转的页面
		String successUrl = request.getParameter("__url");
		if (StringUtils.isBlank(successUrl)){
			successUrl = (String)request.getAttribute("__url");
		}
		// 登录后重定向地址验证，如果是非法地址，则指定默认的登录成功地址
		if (!ServletUtils.isAllowRedirects(request, successUrl) || StringUtils.isBlank(successUrl)){
			successUrl = Global.getProperty("shiro.successUrl");
		}

		// 登录操作如果是Ajax操作，直接返回登录信息字符串。
		if (ServletUtils.isAjaxRequest(request)){
			model.addAttribute("result", Global.TRUE);
			// 如果是登录，则返回登录成功信息，否则返回获取成功信息
			if (isLogin){
				model.addAttribute("message", text("sys.login.success"));
			}else{
				model.addAttribute("message", text("sys.login.getInfo"));
			}
			model.addAttribute("sessionid", (String)session.getId());
			if (!StringUtils.contains(successUrl, "://")){
				successUrl = Global.getCtxPath() + successUrl;
			}
			model.addAttribute("__url", successUrl); // 告诉浏览器登录后跳转的页面
			// 初始密码策略和密码修改策略验证（0：关闭；1：提醒用户；2：强制修改初始或旧密码）
			String modifyPasswordMsg = PwdUtils.getModifyPasswordMsg(user, model);
			model.addAttribute("modifyPasswordMsg", modifyPasswordMsg);
			return ServletUtils.renderObject(response, model);
		}
		// 如果是登录操作，则跳转到登录成功页
		else if (isLogin){
			return REDIRECT + successUrl;
		}

		// API 模式不返回视图页面
		if (Global.isApiMode()) {
			return ServletUtils.renderString(response, "Please visit front-end address.");
		}

		// 是否允许刷新主页，如果已登录，再次访问主页，则退出原账号。
		if (!Global.getConfigToBoolean("shiro.isAllowRefreshIndex", "true")){
			String logined = CookieUtils.getCookie(request, "LOGINED");
			if (StringUtils.isBlank(logined) || "false".equals(logined)){
				CookieUtils.setCookie(response, "LOGINED", "true");
			}else if (StringUtils.equals(logined, "true")){
				UserUtils.getSubject().logout();
				CookieUtils.setCookie(response, "LOGINED", "false");
				String queryString = request.getQueryString();
				queryString = queryString == null ? "" : "?" + queryString;
				return REDIRECT + adminPath + "/login" + queryString;
			}
		}

		// 初始密码策略和密码修改策略验证（0：关闭；1：提醒用户；2：强制修改初始或旧密码）
		String passwordModifyUrl = PwdUtils.passwordModifyValid(user, model);
		if (passwordModifyUrl != null){
			try {
				request.getRequestDispatcher(passwordModifyUrl).forward(request, response);
			} catch (Exception e) {
				logger.error(e.getMessage(), e);
			}
			return null;
		}

		// 非无类型用户，自动根据用户类型设置默认菜单的归属系统（个性化示例）
		//if (!User.USER_TYPE_NONE.equals(user.getUserType())){
		//	session.setAttribute("sysCode", user.getUserType());
		//	UserUtils.removeCache(UserUtils.CACHE_AUTH_INFO+"_"+session.getId());
		//}

		// 登录切换角色身份（个性化示例）
		//String roleCode = "dept";
		//session.setAttribute("roleCode", roleCode);
		//UserUtils.removeCache(UserUtils.CACHE_AUTH_INFO+"_"+session.getId());

		// 返回指定用户类型的首页视图
		String userType = user.getUserType();
		if (User.USER_TYPE_NONE.equals(userType)){
			userType = User.USER_TYPE_EMPLOYEE;
		}
		String view = UserUtils.getUserTypeValue(userType, "indexView");
		if(StringUtils.isNotBlank(view)){
			return view;
		}

		// 返回主页面视图
		return "modules/sys/sysIndex";
	}

@Override
	public User onLoginSuccess(LoginInfo loginInfo, HttpServletRequest request) {
		User user = super.onLoginSuccess(loginInfo, request);

		// 单点登录登出句柄（登录时注入session），在这之前必须获取下授权信息
		String ticket = loginInfo.getParam("ticket");
		casOutHandler.recordSession(request, ticket);
		//System.out.print("__sid: "+request.getSession().getId());
		//System.out.println(" == "+UserUtils.getSession().getId());

		// 记录用户登录日志
		LogUtils.saveLog(user, request, "系统登录", Log.TYPE_LOGIN_LOGOUT);
		return user;
	}

/**
	 * 获取登录用户名
	 */
	protected String getUsername(ServletRequest request, ServletResponse response) {
		String username = super.getUsername(request);
		if (StringUtils.isBlank(username)){
			username = ObjectUtils.toString(request.getAttribute(getUsernameParam()), StringUtils.EMPTY);
		}
		if (StringUtils.length(username) > 1000) {
    		throw new AuthenticationException("msg:"+Global.getText("sys.login.error"));
		}
		// 登录用户名解密（解决登录用户名明文传输安全问题）
		String secretKey = Global.getProperty("shiro.loginSubmit.secretKey");
		if (StringUtils.isNotBlank(username) && StringUtils.isNotBlank(secretKey)){
			username = DesUtils.decode(username, secretKey);
			if (StringUtils.isBlank(username)){
				logger.info("登录账号为空或解码错误.");
			}
		}
		// 登录时判断是否需要记住用户名
		if (WebUtils.isTrue(request, REMEMBER_USERCODE_PARAM)) {
			rememberUserCodeCookie.setValue(EncodeUtils.encodeUrl(EncodeUtils.xssFilter(username, (HttpServletRequest)request)));
			rememberUserCodeCookie.saveTo((HttpServletRequest)request, (HttpServletResponse)response);
		} else {
			rememberUserCodeCookie.removeFrom((HttpServletRequest)request, (HttpServletResponse)response);
		}
		return username;
	}

/**
	 * 获取当前会话的用户信息
	 */
	public String getCurrentUser() {
		User currentUser = UserUtils.getUser();
		if (StringUtils.isBlank(currentUser.getUserCode())) {
			logger.info("当前用户信息 ============== 当前用户未登录。{}", UserUtils.getSession().getId());
			return "当前用户未登录。";
		}
		String result = JsonMapper.toJson(currentUser);
		logger.info("当前用户信息 ============== 查询结果：{}", result);
		return result;
	}

