// 安全认证类

	@Override
	protected boolean preHandle(ServletRequest request, ServletResponse response) throws Exception {
		try{
			Subject subject = getSubject(request, response);
	        String redirectUrl = getRedirectUrl(request, response, subject);
	        //try/catch added for SHIRO-298:
	        try {
	        	Object principal = subject.getPrincipal();
	        	if (principal != null){
	        		LoginInfo loginInfo = (LoginInfo)principal;

	        		// 退出成功之前调用退出事件，方便记录日志等相关销毁工作
	        		authorizingRealm.onLogoutSuccess(loginInfo, (HttpServletRequest)request);

	        		// 设定了用户类型的登录页面，则退出到对应用户类型的登录页面
		        	String userType = loginInfo.getParam("userType");
	        		if(StringUtils.isNotBlank(userType)){
	        			redirectUrl += StringUtils.contains(redirectUrl, "?") ? "&" : "?";
	        			redirectUrl += "param_userType=" + userType;
	        		}
	        	}
	    		// 退出登录	
	    		subject.logout();
	        } catch (SessionException ise) {
	            logger.debug("Encountered session exception during logout.  This can generally safely be ignored.", ise);
	        }

	        // 如果是Ajax请求，返回Json字符串。
	 		if (ServletUtils.isAjaxRequest((HttpServletRequest)request)){
	 			ServletUtils.renderResult((HttpServletResponse)response,
	 					Global.TRUE, Global.getText("sys.logout.success"));
	 			return false;
	 		}

	        issueRedirect(request, response, redirectUrl);
		}catch(Exception e){
			logger.debug("Encountered session exception during logout.  This can generally safely be ignored.", e);
		}
		return false;
	}

/**
	 * 登录页面
	 */
	@RequestMapping(value = "login")
	public String login(HttpServletRequest request, HttpServletResponse response, Model model) {
		// 地址中如果包含JSESSIONID，则跳转一次，去掉JSESSIONID信息。
		if (StringUtils.containsIgnoreCase(request.getRequestURI(), ";JSESSIONID=")){
			redirectUrl(request, response, "/login");
			return null;
		}

		// 如果已经登录，则跳转到管理首页
		Subject subject = UserUtils.getSubject();
		LoginInfo loginInfo = UserUtils.getLoginInfo(subject);
		if(loginInfo != null){
			redirectUrl(request, response, "/index");
			return null;
		}

		// 如果是登录操作，跳转到此，则认为是登录失败（支持GET登录时传递__login=true参数）
		if (WebUtils.isTrue(request, BaseAuthorizingRealm.IS_LOGIN_OPER)){
			return loginFailure(request, response, model);
		}

		// 获取登录数据
		model.addAllAttributes(FormFilter.getLoginData(request, response));

		// 如果是Ajax请求，返回Json字符串。
		if (ServletUtils.isAjaxRequest((HttpServletRequest)request)){
			model.addAttribute("message", text("sys.login.notLongIn"));
			return ServletUtils.renderObject(response, model);
		}

		// API 模式不返回视图页面
		if (Global.isApiMode()) {
			return ServletUtils.renderString(response, "Please visit front-end address.");
		}

		// 返回指定用户类型的登录页视图
		String userType = (String)model.asMap().get(ServletUtils.EXT_PARAMS_PREFIX + "userType");
		if (StringUtils.isBlank(userType)){
			userType = User.USER_TYPE_EMPLOYEE;
		}
		String view = UserUtils.getUserTypeValue(userType, "loginView");
		if(StringUtils.isNotBlank(view)){
			return view;
		}

		return "modules/sys/sysLogin";
	}

