@Override
	protected FormToken getFormToken(AuthenticationToken authcToken) {

		// 单点登录登出句柄（登出时注销session）有CAS中央服务器调用
		HttpServletRequest request = ServletUtils.getRequest();
		if (casOutHandler.isLogoutRequest(request)) {
			LoginInfo loginInfo = casOutHandler.destroySession(request);
			if (loginInfo != null){
				this.onLogoutSuccess(loginInfo, request);
			}
			return null;
		}

		if (authcToken == null){
			return null;
		}

		CasToken casToken = (CasToken) authcToken;
		String ticket = (String) casToken.getCredentials();
		if (ticketValidator == null) {
            ticketValidator = new Cas20ServiceTicketValidator(casServerUrl);
            ((Cas20ServiceTicketValidator)ticketValidator).setEncoding(EncodeUtils.UTF_8);
        }

		// 进行登录身份验证
		Assertion casAssertion = null;
		try {
			casAssertion = ticketValidator.validate(ticket, casServerCallbackUrl);
		} catch (TicketValidationException e) {
			// 令牌失效，在LogoutFilter会自动跳转到登录页
			return null;
		}
		AttributePrincipal casPrincipal = casAssertion.getPrincipal();
		casToken.setUserId(casPrincipal.getName());

		// 生成登录信息对象
		FormToken token = new FormToken(request);
        token.setUsername(casPrincipal.getName());
        Map<String, Object> params = MapUtils.newHashMap();
        params.putAll(casPrincipal.getAttributes());
        params.put("ticket", ticket);
        token.setParams(params);
        return token;
	}

/**
	 * 保存用户员工
	 */
	@Override
	@Transactional
	public void save(EmpUser user) {
		// 1、初始化用户信息
		if (user.getIsNewRecord()){
			// 如果没有设置用户编码，则根据登录名生成一个
			if (StringUtils.isBlank(user.getUserCode())){
				userService.genId(user, user.getLoginCode());
				user.setUserCode(user.getUserCode()+"_"+IdGen.randomShortString());
			}
			user.setUserType(EmpUser.USER_TYPE_EMPLOYEE);
			user.setMgrType(EmpUser.MGR_TYPE_NOT_ADMIN);
		}
		Employee employee = user.getEmployee();
		// 如果员工编码为空，则使用用户编码
		if (StringUtils.isBlank(employee.getEmpCode())){
			employee.setEmpCode(user.getUserCode());
		}
		// 如果员工工号为空，则使用员工编码
		if (StringUtils.isBlank(employee.getEmpNo())){
			employee.setEmpNo(employee.getEmpCode());
		}
		// 如果员工姓名为空，则使用昵称名
		if (StringUtils.isBlank(employee.getEmpName())){
			employee.setEmpName(user.getUserName());
		}
		// 2、保存用户
		user.setRefCode(employee.getEmpCode());
		user.setRefName(employee.getEmpName());
		userService.save(user);
		// 3、保存员工
		employee.setIsNewRecord(user.getIsNewRecord());
		employeeService.save(employee);
		// 4、保存附属机构
		EmployeeOffice employeeOfficeWhere = new EmployeeOffice();
		employeeOfficeWhere.setEmpCode(employee.getEmpCode());
		employeeOfficeDao.deleteByEntity(employeeOfficeWhere);
		if (!employee.getEmployeeOfficeList().isEmpty()){
			employee.getEmployeeOfficeList().forEach(employeeOffice -> {
				employeeOffice.setId(IdGen.nextId());
				employeeOffice.setEmpCode(employee.getEmpCode());
			});
			employeeOfficeDao.insertBatch(employee.getEmployeeOfficeList(), null);
		}
	}

