public static State saveFileByInputStream(InputStream is, String path, long maxSize) {
        State state = null;
        File tmpFile = getTmpFile();
        byte[] dataBuf = new byte[2048];
        try (BufferedInputStream bis = new BufferedInputStream(is, StorageManager.BUFFER_SIZE)) {
            try (BufferedOutputStream bos = new BufferedOutputStream(new FileOutputStream(tmpFile), StorageManager.BUFFER_SIZE)) {
                int count = 0;
                while ((count = bis.read(dataBuf)) != -1) {
                    bos.write(dataBuf, 0, count);
                }
            }

            if (tmpFile.length() > maxSize) {
                tmpFile.delete();
                return new BaseState(false, AppInfo.MAX_SIZE);
            }

            // 验证允许的上传的文件类型（如果没有设置则不验证，默认不设置）
            String allowContentTypes = PropertiesUtils.getInstance()
                    .getProperty("file.allowContentTypes");
            if (StringUtils.isNotBlank(allowContentTypes)) {
                String rct = FileUtils.getRealContentType(tmpFile);
                if (!StringUtils.inString(rct, allowContentTypes.split(","))) {
                    tmpFile.delete();
                    return new BaseState(false, AppInfo.NOT_ALLOW_FILE_TYPE);
                }
            }
            state = saveTmpFile(tmpFile, path);
            if (!state.isSuccess()) {
                tmpFile.delete();
            }
            return state;
        } catch (IOException ignored) {
            ;
        }
        return new BaseState(false, AppInfo.IO_ERROR);
    }

