	/**
	 * 单点登录（如已经登录，则直接跳转）
	 * @param username 	登录用户名（loginCode）
	 * @param token 	单点登录令牌，令牌组成：sso密钥+用户名+日期，进行md5加密，举例： 
	 * 		// 注意如果 shiro.sso.encryptKey 为 true，则 secretKey 会自动加密。
	 * 		String secretKey = Global.getConfig("shiro.sso.secretKey");
	 * 		String token = Md5Utils.md5(secretKey + username + DateUtils.getDate("yyyyMMdd"));
	 * @param params 	登录附加参数（JSON格式），或 param_ 前缀的请求参数。
	 * @param url 		登录成功后跳转的url地址。
	 * @param relogin 	是否强制重新登录，需要强制重新登录传递true
	 * @see 调用示例：
	 * 	http://localhost/project/sso/{username}/{token}?url=/sys/user/list?p1=v1%26p2=v2&relogin=true
	 * 	如果url中携带参数，请使用转义字符，如“&”号，使用“%26”转义。
	 */
	@RequestMapping(value = "sso/{username}/{token}")
	public String sso(@PathVariable String username, @PathVariable String token,
			@RequestParam(defaultValue="${adminPath}/index") String url, String relogin,
			HttpServletRequest request, HttpServletResponse response, Model model){
		// 如果已经登录，并且是同一个人，并且不强制重新登录，则直接跳转到目标页
		User user = UserUtils.getUser();
		if(StringUtils.isNotBlank(user.getUserCode())
				&& StringUtils.equals(user.getLoginCode(), username)
				&& !ObjectUtils.toBoolean(relogin)){
			if (ServletUtils.isAjaxRequest(request)){
				return ServletUtils.renderResult(response, Global.TRUE, text("账号已登录"));
			}else{
				return REDIRECT + EncodeUtils.decodeUrl2(url);
			}
		}
		// 通过令牌登录系统
		if (token != null){
			try {
				// FormToken 构造方法的三个参数：登录名、单点登录的令牌秘钥、请求对象
				UserUtils.getSubject().login(new FormToken(username, token, request));
				request.setAttribute("__url", EncodeUtils.decodeUrl2(url));
				FormFilter.onLoginSuccess(request, response);
	        } catch (AuthenticationException e) {
	        	FormFilter.onLoginFailure(e, request, response);
	        }
			return null;
		}
		return "error/403";
	}

/**
	 * 校验密保问题答案
	 */
	@PostMapping(value = "savePwdByPwdQuestion")
	@ResponseBody
	@Operation(summary = "根据保密问题重置密码")
	@Parameters({
		@Parameter(name = "loginCode", description = "登录账号", required = true),
		@Parameter(name = "pwdQuestionAnswer", description = "保密问题答案（1）", required = true),
		@Parameter(name = "pwdQuestionAnswer2", description = "保密问题答案（2）", required = true),
		@Parameter(name = "pwdQuestionAnswer3", description = "保密问题答案（3）", required = true),
		@Parameter(name = "password", description = "新密码", required = true),
	})
	public String savePwdByPwdQuestion(User user, HttpServletRequest request) {
		String userCode = UserUtils.getCache("fpUserCode");
		String loginCode = UserUtils.getCache("fpLoginCode");

		// 一同验证保存的用户名和验证码是否正确（如果只校验验证码，不验证用户名，则会有获取验证码后修改用户名的漏洞）
		if (!(userCode != null && loginCode != null && loginCode.equals(user.getLoginCode()))){
			return renderResult(Global.FALSE, text("请重新获取保密问题！"));
		}

		String secretKey = Global.getProperty("shiro.loginSubmit.secretKey");
		if (StringUtils.isNotBlank(secretKey)){
			user.setPwdQuestionAnswer(DesUtils.decode(user.getPwdQuestionAnswer(), secretKey));
			user.setPwdQuestionAnswer2(DesUtils.decode(user.getPwdQuestionAnswer2(), secretKey));
			user.setPwdQuestionAnswer3(DesUtils.decode(user.getPwdQuestionAnswer3(), secretKey));
			user.setPassword(DesUtils.decode(user.getPassword(), secretKey));
		}

		// 验证三个密保问题是否正确。
		User u = UserUtils.get(userCode);
		if (!(u != null && loginCode.equals(user.getLoginCode())
				&& PwdUtils.validatePassword(user.getPwdQuestionAnswer(), u.getPwdQuestionAnswer())
				&& PwdUtils.validatePassword(user.getPwdQuestionAnswer2(), u.getPwdQuestionAnswer2())
				&& PwdUtils.validatePassword(user.getPwdQuestionAnswer3(), u.getPwdQuestionAnswer3()))) {
			return renderResult(Global.FALSE, text("您填写的密保问题答案不正确！"));
		}

		// 更新为新密码。
		try{
			userService.updatePassword(userCode, user.getPassword());
		}catch(ServiceException se){
			return renderResult(Global.FALSE, se.getMessage());
		}

		// 更新密码后，清理缓存
		UserUtils.removeCache("fpUserCode");
		UserUtils.removeCache("fpLoginCode");

		return renderResult(Global.TRUE, text("恭喜你，您的账号 {0} 密码找回成功！", user.getLoginCode()));
	}

/**
	 * 获取登录用户名
	 */
	protected String getUsername(ServletRequest request, ServletResponse response) {
		String username = super.getUsername(request);
		if (StringUtils.isBlank(username)){
			username = ObjectUtils.toString(request.getAttribute(getUsernameParam()), StringUtils.EMPTY);
		}
		if (StringUtils.length(username) > 1000) {
    		throw new AuthenticationException("msg:"+Global.getText("sys.login.error"));
		}
		// 登录用户名解密（解决登录用户名明文传输安全问题）
		String secretKey = Global.getProperty("shiro.loginSubmit.secretKey");
		if (StringUtils.isNotBlank(username) && StringUtils.isNotBlank(secretKey)){
			username = DesUtils.decode(username, secretKey);
			if (StringUtils.isBlank(username)){
				logger.info("登录账号为空或解码错误.");
			}
		}
		// 登录时判断是否需要记住用户名
		if (WebUtils.isTrue(request, REMEMBER_USERCODE_PARAM)) {
			rememberUserCodeCookie.setValue(EncodeUtils.encodeUrl(EncodeUtils.xssFilter(username, (HttpServletRequest)request)));
			rememberUserCodeCookie.saveTo((HttpServletRequest)request, (HttpServletResponse)response);
		} else {
			rememberUserCodeCookie.removeFrom((HttpServletRequest)request, (HttpServletResponse)response);
		}
		return username;
	}

/**
	 * 登录成功，进入管理首页
	 */
	@RequestMapping(value = "index")
	public String index(HttpServletRequest request, HttpServletResponse response, Model model) {
		// 地址中如果包含JSESSIONID，则跳转一次，去掉JSESSIONID信息。
		if (StringUtils.containsIgnoreCase(request.getRequestURI(), ";JSESSIONID=")){
			redirectUrl(request, response, "/index");
			return null;
		}

		// 获取登录用户信息，未加载shiro模块时会为空，直接访问则提示操作权限不足。
		Subject subject = UserUtils.getSubject();
		LoginInfo loginInfo = UserUtils.getLoginInfo(subject);
		if(loginInfo == null){
			subject.logout();
			redirectUrl(request, response, "/login");
			return null;
		}

		// 当前用户对象信息
		User user = UserUtils.get(loginInfo.getId());
		if (user == null){
			subject.logout();
			redirectUrl(request, response, "/login");
			return null;
		}

		// 如果是登录操作，则初始化一些登录参数
		Session session = UserUtils.getSession(subject);
		boolean isLogin = Global.TRUE.equals(session.getAttribute(BaseAuthorizingRealm.IS_LOGIN_OPER));
		if (isLogin){
			// 清除登录状态，防止下次调用误认为是登录
			session.removeAttribute(BaseAuthorizingRealm.IS_LOGIN_OPER);

			// 设置共享SessionId的Cookie值（第三方系统使用）
			String cookieName = Global.getProperty("session.shareSessionIdCookieName");
			if (StringUtils.isNotBlank(cookieName)){
				CookieUtils.setCookie(response, cookieName, (String)session.getId(), "/");
			}

			// 如果登录设置了语言，则切换语言
			if (loginInfo.getParam("lang") != null){
				Global.setLang(loginInfo.getParam("lang"), request, response);
			}

			// 根据当前用户子系统，切换到默认系统下
			for(Role role : user.getRoleList()) {
				if (role.getSysCodes() != null) {
					String sysCode = null;
					for (String code : StringUtils.splitComma(role.getSysCodes())) {
						if (StringUtils.isNotBlank(code)) {
							sysCode = code;
							break;
						}
					}
					if (sysCode != null) {
						session.setAttribute("sysCode", sysCode);
						MenuUtils.clearAuthInfo(session);
						break;
					}
				}
			}
		}

		// 验证下用户权限，以便调用doGetAuthorizationInfo方法
		else if (!subject.isPermitted("user")){
			subject.logout();
			redirectUrl(request, response, "/login");
			return null;
		}

		// 获取当前会话对象，并返回一些数据
		if (!StringUtils.equals(request.getParameter("__be"), Global.YES)) {
			model.addAllAttributes(FormFilter.getLoginSuccessData(request, response, user, session));
		}

		// 获取登录成功后跳转的页面
		String successUrl = request.getParameter("__url");
		if (StringUtils.isBlank(successUrl)){
			successUrl = (String)request.getAttribute("__url");
		}
		// 登录后重定向地址验证，如果是非法地址，则指定默认的登录成功地址
		if (!ServletUtils.isAllowRedirects(request, successUrl) || StringUtils.isBlank(successUrl)){
			successUrl = Global.getProperty("shiro.successUrl");
		}

		// 登录操作如果是Ajax操作，直接返回登录信息字符串。
		if (ServletUtils.isAjaxRequest(request)){
			model.addAttribute("result", Global.TRUE);
			// 如果是登录，则返回登录成功信息，否则返回获取成功信息
			if (isLogin){
				model.addAttribute("message", text("sys.login.success"));
			}else{
				model.addAttribute("message", text("sys.login.getInfo"));
			}
			model.addAttribute("sessionid", (String)session.getId());
			if (!StringUtils.contains(successUrl, "://")){
				successUrl = Global.getCtxPath() + successUrl;
			}
			model.addAttribute("__url", successUrl); // 告诉浏览器登录后跳转的页面
			// 初始密码策略和密码修改策略验证（0：关闭；1：提醒用户；2：强制修改初始或旧密码）
			String modifyPasswordMsg = PwdUtils.getModifyPasswordMsg(user, model);
			model.addAttribute("modifyPasswordMsg", modifyPasswordMsg);
			return ServletUtils.renderObject(response, model);
		}
		// 如果是登录操作，则跳转到登录成功页
		else if (isLogin){
			return REDIRECT + successUrl;
		}

		// API 模式不返回视图页面
		if (Global.isApiMode()) {
			return ServletUtils.renderString(response, "Please visit front-end address.");
		}

		// 是否允许刷新主页，如果已登录，再次访问主页，则退出原账号。
		if (!Global.getConfigToBoolean("shiro.isAllowRefreshIndex", "true")){
			String logined = CookieUtils.getCookie(request, "LOGINED");
			if (StringUtils.isBlank(logined) || "false".equals(logined)){
				CookieUtils.setCookie(response, "LOGINED", "true");
			}else if (StringUtils.equals(logined, "true")){
				UserUtils.getSubject().logout();
				CookieUtils.setCookie(response, "LOGINED", "false");
				String queryString = request.getQueryString();
				queryString = queryString == null ? "" : "?" + queryString;
				return REDIRECT + adminPath + "/login" + queryString;
			}
		}

		// 初始密码策略和密码修改策略验证（0：关闭；1：提醒用户；2：强制修改初始或旧密码）
		String passwordModifyUrl = PwdUtils.passwordModifyValid(user, model);
		if (passwordModifyUrl != null){
			try {
				request.getRequestDispatcher(passwordModifyUrl).forward(request, response);
			} catch (Exception e) {
				logger.error(e.getMessage(), e);
			}
			return null;
		}

		// 非无类型用户，自动根据用户类型设置默认菜单的归属系统（个性化示例）
		//if (!User.USER_TYPE_NONE.equals(user.getUserType())){
		//	session.setAttribute("sysCode", user.getUserType());
		//	UserUtils.removeCache(UserUtils.CACHE_AUTH_INFO+"_"+session.getId());
		//}

		// 登录切换角色身份（个性化示例）
		//String roleCode = "dept";
		//session.setAttribute("roleCode", roleCode);
		//UserUtils.removeCache(UserUtils.CACHE_AUTH_INFO+"_"+session.getId());

		// 返回指定用户类型的首页视图
		String userType = user.getUserType();
		if (User.USER_TYPE_NONE.equals(userType)){
			userType = User.USER_TYPE_EMPLOYEE;
		}
		String view = UserUtils.getUserTypeValue(userType, "indexView");
		if(StringUtils.isNotBlank(view)){
			return view;
		}

		// 返回主页面视图
		return "modules/sys/sysIndex";
	}

@Override
	protected User getUserInfo(FormToken token) {

		User user = super.getUserInfo(token);
		if (user == null){
			Map<String, Object> attrs = token.getParams();

			// 如果允许客户端创建账号，则创建账号
			if (ObjectUtils.toBoolean(attrs.get("isAllowClientCreateUser"))){

				// 获取CAS传递过来的用户属性信息
				user = new User(EncodeUtils.decodeUrl(ObjectUtils.toString(attrs.get("userCode"))));
				user.setLoginCode(EncodeUtils.decodeUrl(ObjectUtils.toString(attrs.get("loginCode"))));
				user.setCorpCode_(EncodeUtils.decodeUrl(ObjectUtils.toString(attrs.get("corpCode"))));
				user.setPassword(EncodeUtils.decodeUrl(ObjectUtils.toString(attrs.get("password"))));
				user.setUserName(EncodeUtils.decodeUrl(ObjectUtils.toString(attrs.get("userName"))));
				user.setEmail(EncodeUtils.decodeUrl(ObjectUtils.toString(attrs.get("email"))));
				user.setMobile(EncodeUtils.decodeUrl(ObjectUtils.toString(attrs.get("mobile"))));
				user.setPhone(EncodeUtils.decodeUrl(ObjectUtils.toString(attrs.get("phone"))));
				user.setUserType(EncodeUtils.decodeUrl(ObjectUtils.toString(attrs.get("userType"))));
				user.setRefCode(EncodeUtils.decodeUrl(ObjectUtils.toString(attrs.get("refCode"))));
				user.setRefName(EncodeUtils.decodeUrl(ObjectUtils.toString(attrs.get("refName"))));
				user.setMgrType(EncodeUtils.decodeUrl(ObjectUtils.toString(attrs.get("mgrType"))));
				user.setStatus(EncodeUtils.decodeUrl(ObjectUtils.toString(attrs.get("status"))));

				// 如果是员工类型，则平台自动创建
				if (User.USER_TYPE_EMPLOYEE.equals(user.getUserType())){

					// 保存员工和用户
					try{
						EmpUser empUser = new EmpUser();
						empUser.setIsNewRecord(true);
						empUser.setMobile(user.getMobile());
						empUser.setEmail(user.getEmail());
						empUser.setPhone(user.getPhone());
						empUser.getEmployee().getCompany().setCompanyCode(EncodeUtils
								.decodeUrl(ObjectUtils.toString(attrs.get("companyCode"))));
						empUser.getEmployee().getOffice().setOfficeCode(EncodeUtils
								.decodeUrl(ObjectUtils.toString(attrs.get("officeCode"))));
						getEmpUserService().save(empUser);
					}catch(ValidationException ve){
						throw new AuthenticationException("msg:" + ve.getMessage());
					}

					// 重新获取用户登录
					user = UserUtils.getByLoginCode(token.getUsername(), user.getCorpCode_());
					if (user != null) {
						return user;
					}

				}

				// 其它类型，根据项目需要自行创建
				else{
					User finalUser = user;
					SpringUtils.getBeanIfAvailable(CasCreateUser.class, (casCreateUser) -> {
						casCreateUser.createUser(finalUser, attrs);
					}, (e -> {
						throw new AuthenticationException("msg:用户 “" + token.getUsername()
								+ "”, 类型 “" + finalUser.getUserType() + "” 在本系统中不存在, 请联系管理员.");
					}));
				}
			}else{
				throw new AuthenticationException("msg:用户 “" + token.getUsername() + "” 在本系统中不存在, 请联系管理员.");
			}
		}
		return user;
	}

